import {
  app,
  BrowserWindow,
  ipcMain,
  shell,
  systemPreferences,
} from "electron";
import { getHotkeyManager } from "./main/hotkey";
import { isMac } from "./main/platform";

// Webpack entry point declarations (auto-generated by Forge's Webpack plugin)
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require("electron-squirrel-startup")) {
  app.quit();
}

const gotSingleInstanceLock = app.requestSingleInstanceLock();
if (!gotSingleInstanceLock) {
  app.quit();
}

// `npm start` runs the generic Electron binary; show our name in the menu bar and Dock.
if (isMac) {
  app.setName("Baymax");
}

let mainWindow: BrowserWindow | null = null;
// Current state is kept here so a renderer that mounts (or reloads) mid-hold can ask for it.
let holdState: "idle" | "listening" = "idle";

function getAccessibilityStatus(): boolean | null {
  if (!isMac) return null;
  return systemPreferences.isTrustedAccessibilityClient(false);
}

function createWindow(): void {
  mainWindow = new BrowserWindow({
    width: 360,
    height: 200,
    title: "Baymax",
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      contextIsolation: true,
      nodeIntegration: false,
    },
  });
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);
  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

function sendHoldState(state: "idle" | "listening"): void {
  holdState = state;
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send("hold-state", state);
  }
}

if (gotSingleInstanceLock) {
  app.on("second-instance", () => {
    if (mainWindow) {
      if (mainWindow.isMinimized()) mainWindow.restore();
      mainWindow.focus();
    }
  });

  app.whenReady().then(() => {
    // One snapshot for both the hook guard and the renderer hint, so they never disagree.
    const accessibilityAtStartup = getAccessibilityStatus();

    ipcMain.handle("get-permissions", () => ({
      accessibility: accessibilityAtStartup,
      platform: process.platform,
    }));

    ipcMain.on("get-hold-state", (event) => {
      event.sender.send("hold-state", holdState);
    });

    // Only fired by the explicit button in the window.
    ipcMain.on("open-accessibility-settings", () => {
      if (!isMac) return;
      systemPreferences.isTrustedAccessibilityClient(true);
      shell.openExternal(
        "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility",
      );
    });

    createWindow();

    // Handlers first, then start the hook, so the first key event is never missed.
    const hotkeyManager = getHotkeyManager();
    hotkeyManager.on("recording-start", () => sendHoldState("listening"));
    hotkeyManager.on("recording-stop", () => sendHoldState("idle"));

    if (!isMac || accessibilityAtStartup) {
      hotkeyManager.start();
    } else {
      console.log(
        "[Hotkey] Waiting for Accessibility permission; listener not started",
      );
    }
  });

  app.on("window-all-closed", () => {
    app.quit();
  });

  app.on("will-quit", () => {
    getHotkeyManager().stop();
  });
}
